import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { isMockLineId } from "../../../[token]/_live/mock-lines";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * One of the mock interviewer's spoken clips, for the live screen demo only
 * (/interview/preview-live): 24 kHz mono s16le PCM, generated by
 * dev-assets/mock-voice/generate.mjs.
 *
 * Development only: a production build answers 404 before anything is read.
 * Only the clip ids in mock-lines.ts are served, so no other path can be
 * named. The candidate page never fetches these.
 */
export async function GET(_request: Request, { params }: { params: Promise<{ clip: string }> }) {
  if (process.env.NODE_ENV === "production") return new Response(null, { status: 404 });
  const { clip } = await params;
  if (!isMockLineId(clip)) return new Response(null, { status: 404 });
  try {
    const bytes = await readFile(join(process.cwd(), "dev-assets", "mock-voice", `${clip}.pcm`));
    return new Response(new Uint8Array(bytes), {
      headers: { "content-type": "application/octet-stream", "cache-control": "no-store" },
    });
  } catch {
    return new Response(null, { status: 404 });
  }
}
